# 生成CURRICULUM_REFINEMENTS JS
refine_entries = []
for lid in range(1, 33):
    r = refinements[lid]
    t = r['transfer']
    refine_entries.append('  %d:{meaning:"%s",observe:"%s",hook:"%s",goal:"%s",watch:"%s",transfer:{name:"%s",eff:"%s",steps:[%s],challenge:"%s"}}' % (
        lid, r['meaning'], r['observe'], r['hook'], r['goal'], r['watch'],
        t['name'], t['eff'],
        ','.join('"%s"' % s.replace('"','\\"') for s in t['steps']),
        t['challenge']))
new_refine = 'const CURRICULUM_REFINEMENTS = {\n' + ',\n'.join(refine_entries) + '\n};'

refine_pattern = re.compile(r'const CURRICULUM_REFINEMENTS = \{.*?\};', re.DOTALL)
content, n = refine_pattern.subn(new_refine, content, count=1)
print(f"CURRICULUM_REFINEMENTS 替换: {'✓' if n else '✗'}")

